/**
 * Renders the example diagrams used as figures in the manuscript.
 *
 * Output is vector PDF, produced by the library's own PDF backend, so the
 * figures in the paper are generated by the software they describe.
 *
 * Usage: `node benchmarks/figures.js <output-directory>`
 *
 * SPDX-License-Identifier: MIT
 * Copyright (c) 2026 Claudio Esperança and contributors
 */

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import {
  sankeyLayers, sankeyAddDummies, sankeyOrderNodes,
  sankeyGeometricLayout, sankeyRenderLayout
} from "../src/layout/index.js";
import { buildScene } from "../src/render/scene.js";
import { paintScene } from "../src/render/theme.js";
import { sceneToPDF } from "../src/render/pdf.js";
import { measureScene } from "../src/metrics/index.js";
import { addTotalizingNodes } from "../src/data/synthetic.js";
import { energySumNodes, energyCategories, energyColors } from "../src/data/energy.js";
import { randomLcg } from "../src/internal/random.js";

const here = dirname(fileURLToPath(import.meta.url));
const outDir = process.argv[2] ?? join(here, "out", "figures");
mkdirSync(outDir, { recursive: true });

const { links } = JSON.parse(
  readFileSync(join(here, "datasets", "energy-05.json"), "utf8")
);

const palette = new Map(energyCategories.map((c, i) => [c, energyColors[i]]));
const colorScale = (/** @type {string} */ key) => palette.get(key) ?? "#8a8a8a";

/**
 * @param {object} opts
 * @param {any[]} opts.data
 * @param {string[]} [opts.hidden]
 * @param {boolean} [opts.joinDummies]
 * @param {number} [opts.marginLeft]
 */
function render({ data, hidden, joinDummies = false, marginLeft = 6 }) {
  const width = 700;
  const height = 265;
  const layout = sankeyAddDummies(
    sankeyLayers({ links: data, hidden }, { nodeAlign: "center" })
  );
  sankeyOrderNodes(layout, { nsteps: 60, random: randomLcg(4) });
  const geometry = sankeyGeometricLayout(layout, {
    size: height, whitespace: 0.32, margin: 10, joinDummies
  });
  const renderLayout = sankeyRenderLayout(geometry, {
    length: width, marginLeft, marginRight: 6
  });
  const scene = buildScene(renderLayout, {
    width, height, bias: 1, maxAngle: 20, nodeLabelPadding: 5
  });
  const painted = paintScene(scene, {
    colorScale, pathColor: "source", pathOpacity: 0.55,
    nodeStrokeWidth: 0.4, labelFont: "11px sans-serif"
  });
  return { painted, metrics: measureScene(scene, { sampleScale: 2 }) };
}

/** @type {{name: string, opts: any}[]} */
const figures = [
  { name: "fig-plain", opts: { data: links } },
  { name: "fig-packed", opts: { data: links, joinDummies: true } },
  {
    name: "fig-totalizing",
    opts: { data: addTotalizingNodes(links, energySumNodes), joinDummies: true }
  },
  {
    name: "fig-hidden",
    opts: {
      data: addTotalizingNodes(links, energySumNodes),
      hidden: ["Imp.", "Exp.", "Heat & Waste"],
      joinDummies: true,
      marginLeft: 26
    }
  }
];

for (const { name, opts } of figures) {
  const { painted, metrics } = render(opts);
  writeFileSync(join(outDir, `${name}.pdf`), sceneToPDF(painted, { title: name }));
  console.log(
    `${name.padEnd(16)} crossings ${String(metrics.crossings).padStart(4)}  ` +
      `overlap ${(100 * metrics.overlapRatio).toFixed(2).padStart(5)}%  ` +
      `boxes ${String(painted.nodes.length).padStart(3)}`
  );
}
